<?php

declare(strict_types=1);

namespace PaymentModule\Models;

use Illuminate\Database\Eloquent\Builder;
use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use PaymentModule\Database\Factories\PaymentFactory;
use PaymentModule\Enums\PaymentStatus;

/**
 * A single payment attempt.
 *
 * @property int                 $id
 * @property string              $order_id        Unique reference generated by this package.
 * @property int|null            $user_id         Owner, null for guest payments.
 * @property string              $gateway         Multipay driver name, e.g. "zarinpal".
 * @property int                 $amount          In the gateway currency (Toman or Rial).
 * @property PaymentStatus       $status
 * @property string|null         $transaction_id  Identifier issued by the gateway on purchase.
 * @property string|null         $reference_id    Bank reference issued after a successful verify.
 * @property string|null         $failure_reason  Why the payment failed (internal, never shown to customers).
 * @property \Carbon\Carbon|null $paid_at
 */
class Payment extends Model
{
    use HasFactory;

    protected $fillable = [
        'order_id',
        'user_id',
        'gateway',
        'amount',
        'status',
        'transaction_id',
        'reference_id',
        'failure_reason',
        'paid_at',
    ];

    protected $casts = [
        'amount' => 'integer',
        'status' => PaymentStatus::class,
        'paid_at' => 'datetime',
    ];

    /** The table name is configurable so it can match the host application. */
    public function getTable(): string
    {
        return config('payment-module.table', 'payments');
    }

    protected static function newFactory(): PaymentFactory
    {
        return PaymentFactory::new();
    }

    /** Owner of the payment, resolved from the application's auth configuration. */
    public function user(): BelongsTo
    {
        return $this->belongsTo(config('auth.providers.users.model'), 'user_id');
    }

    /* ------------------------------------------------------------------ *
     | Scopes
     * ------------------------------------------------------------------ */

    public function scopePending(Builder $query): Builder
    {
        return $query->where('status', PaymentStatus::Pending->value);
    }

    public function scopeSuccessful(Builder $query): Builder
    {
        return $query->where('status', PaymentStatus::Success->value);
    }

    public function scopeFailed(Builder $query): Builder
    {
        return $query->where('status', PaymentStatus::Failed->value);
    }

    /* ------------------------------------------------------------------ *
     | State helpers
     * ------------------------------------------------------------------ */

    public function isPending(): bool
    {
        return $this->status === PaymentStatus::Pending;
    }

    public function isSuccessful(): bool
    {
        return $this->status === PaymentStatus::Success;
    }

    public function isFailed(): bool
    {
        return $this->status === PaymentStatus::Failed;
    }

    /** Flag the payment as paid and store the bank reference. */
    public function markAsPaid(string $referenceId): self
    {
        $this->forceFill([
            'status' => PaymentStatus::Success,
            'reference_id' => $referenceId,
            'failure_reason' => null,
            'paid_at' => now(),
        ])->save();

        return $this;
    }

    /** Flag the payment as failed and keep the reason for troubleshooting. */
    public function markAsFailed(?string $reason = null): self
    {
        $this->forceFill([
            'status' => PaymentStatus::Failed,
            'failure_reason' => $reason !== null ? mb_substr($reason, 0, 255) : null,
        ])->save();

        return $this;
    }
}
